#include <iostream>
#include <memory>
using namespace std;

class Vehicle {
public:
    virtual void drive() = 0;
    virtual ~Vehicle() {}
};

class Car : public Vehicle {
public:
    void drive() override { cout << "Driving a car\n"; }
};

class Motorcycle : public Vehicle {
public:
    void drive() override { cout << "Riding a motorcycle\n"; }
};

class VehicleFactory {
public:
    static unique_ptr<Vehicle> create(const string& type) {
        if (type == "car") return make_unique<Car>();
        if (type == "motorcycle") return make_unique<Motorcycle>();
        return nullptr;
    }
};

int main() {
    auto car = VehicleFactory::create("car");
    auto motorcycle = VehicleFactory::create("motorcycle");
    car->drive();
    motorcycle->drive();
    return 0;
}
